async def create_bootservice_workpackage(client, instruction: Instruction):
    best_block = await client.bestBlock()
    block_hash = best_block[0]
    block_timeslot = best_block[1]

    state_root = await client.stateRoot(block_hash)
    beefy_root = await client.beefyRoot(block_hash)

    authorizer = Authorizer(
        code_hash=bytes.fromhex('e29d48602a9bbdb9b19dad28a1c0294087403334ca5bcd2dfaa0f0ec2617e4f6'),
        params=b''
    )

    context = RefinementContext(
        anchor=block_hash,
        state_root=state_root,
        beefy_root=beefy_root,
        lookup_anchor=block_hash,
        lookup_anchor_slot=block_timeslot,
        prerequisites=[]
    )

    work_package = WorkPackage(
        authorization=b'',
        auth_code_host=0,
        authorizer=authorizer,
        context=context,
        items=[
            WorkItem(
                accumulate_gas_limit=10000000,
                code_hash=bytes.fromhex('6c63e601e26279872a93b9b443aa52ad1c26e795647f63c0b7e0abff0d3680da'),
                export_count=0,
                extrinsic=[],
                import_segments=[],
                payload=instruction.to_jam_bytes().to_bytes(),
                refine_gas_limit=5000000000,
                service=0
            )
        ]
    )

    return work_package



